  xm6 N003 N003 N004 0 sky130_fd_pr__nfet_01v8 w={W_xm6} l={L_xm6}
.ends SUB_1
* --- DUT END ---

* Stimulus
Vinp Vinp 0 dc 500m pulse(0.2 0.8 1n 10p 10p 10n 20n)

.control
  * 1. DC Operating Point
  op
  let quiescent_current = -i(VDD)
  print quiescent_current

  * 2. DC Sweep for Gain and Common-Mode
  dc Vinp 0.4 0.6 0.001
  let vdiff = v(vop) - v(vom)
  let diff_gain = deriv(vdiff)
  meas dc max_dc_gain max diff_gain
  meas dc v_cross find v(vop) when v(vop)=v(vom)
  print max_dc_gain v_cross

  * 3. Transient for Slew Rate
  tran 10p 20n
  * Measure slew rate on vop (rising edge)
  meas tran t_rise trig v(vop) val=0.5 rise=1 targ v(vop) val=1.3 rise=1
  let sr_vop_rise = (1.3 - 0.5) / t_rise
  print sr_vop_rise

  quit
.endc
.end

